  ($qb$S14C10Q03$qb$, $qb$S14$qb$, $qb$C10$qb$, $qb$L$qb$, $qb$Record-keeping for compliance purposes (audit trails, evidence of compliance activities) is:$qb$, $qb$Comprehensive — records are complete, secure, and readily available for audit or inspection$qb$, $qb$Generally adequate — most compliance activities are documented$qb$, $qb$Inconsistent — record-keeping quality varies across compliance areas$qb$, $qb$Poor — compliance records are incomplete and the organisation could not adequately defend itself in an audit$qb$, 5, 3, 2, 1, true),
  ($qb$S14C10Q04$qb$, $qb$S14$qb$, $qb$C10$qb$, $qb$L$qb$, $qb$Policy version control and distribution in your organisation is:$qb$, $qb$Well-managed — all employees access the current version of all policies and old versions are archived$qb$, $qb$Generally managed — policy distribution is mostly current$qb$, $qb$Inconsistent — some employees may be working from outdated policy versions$qb$, $qb$Poor — policy version control is not managed and employees may be following outdated guidance$qb$, 5, 3, 2, 1, true),
  ($qb$S14C10Q05$qb$, $qb$S14$qb$, $qb$C10$qb$, $qb$L$qb$, $qb$Digital compliance training delivery and completion tracking is:$qb$, $qb$Systematic — all mandatory compliance training is delivered digitally with completion tracked and enforced$qb$, $qb$Generally managed — most compliance training completion is tracked$qb$, $qb$Partial — some compliance training is tracked; other mandatory training is not$qb$, $qb$Non-existent — compliance training completion is not tracked$qb$, 5, 3, 2, 1, true),
  ($qb$S14C10Q06$qb$, $qb$S14$qb$, $qb$C10$qb$, $qb$L$qb$, $qb$Regulatory filing and submission management in your organisation is:$qb$, $qb$Automated and tracked — all regulatory filing deadlines are tracked and submissions are managed proactively$qb$, $qb$Generally managed — most regulatory filings are tracked and submitted on time$qb$, $qb$Partially managed — some regulatory filing deadlines are managed; others are at risk$qb$, $qb$Poorly managed — regulatory filing deadlines are not systematically tracked$qb$, 5, 3, 2, 1, true),
  ($qb$S14C10Q07$qb$, $qb$S14$qb$, $qb$C10$qb$, $qb$L$qb$, $qb$Data retention and destruction policies in your organisation are:$qb$, $qb$Fully compliant — retention schedules are defined, applied, and records are destroyed when required$qb$, $qb$Generally compliant — most data retention requirements are met$qb$, $qb$Partially compliant — some data retention compliance gaps exist$qb$, $qb$Non-compliant — data retention and destruction policies are not adequately managed$qb$, 5, 3, 2, 1, true),
  ($qb$S14C10Q08$qb$, $qb$S14$qb$, $qb$C10$qb$, $qb$L$qb$, $qb$Third-party compliance documentation (supplier declarations, certificates, audit reports) is:$qb$, $qb$Comprehensively maintained — all required third-party compliance evidence is current and accessible$qb$, $qb$Generally maintained — key third-party documents are available$qb$, $qb$Inconsistently maintained — some third-party compliance evidence is available; other documents are missing$qb$, $qb$Poorly maintained — third-party compliance documentation is incomplete and not reliable$qb$, 5, 3, 2, 1, true),
  ($qb$S14C10Q09$qb$, $qb$S14$qb$, $qb$C10$qb$, $qb$L$qb$, $qb$The organisation's use of technology to monitor and detect compliance risks is:$qb$, $qb$Advanced — monitoring tools proactively identify compliance risks before they become violations$qb$, $qb$Developing — some monitoring technology is in use$qb$, $qb$Limited — compliance risk monitoring is primarily manual$qb$, $qb$Non-existent — the organisation does not use technology to monitor compliance risks$qb$, 5, 3, 2, 1, true),
  ($qb$S14C10Q10$qb$, $qb$S14$qb$, $qb$C10$qb$, $qb$L$qb$, $qb$Overall, compliance technology and documentation in your organisation:$qb$, $qb$Is a genuine capability strength — technology and documentation support effective compliance management$qb$, $qb$Is adequate — documentation and systems meet current compliance needs$qb$, $qb$Has notable gaps — documentation and technology weaknesses create compliance risk$qb$, $qb$Is a serious concern — poor compliance documentation and systems are creating material risk$qb$, 5, 3, 2, 1, true)
INSERT INTO question_bank (question_id, section_code, category_code, level_tag, text, option_a, option_b, option_c, option_d, score_a, score_b, score_c, score_d, active) VALUES
  ($qb$S15C01Q01$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$The organisation's growth ambition and vision is:$qb$, $qb$Clearly articulated, inspiring, and understood across the organisation$qb$, $qb$Generally clear — leadership knows the ambition but it is not always communicated compellingly$qb$, $qb$Vague — the growth vision is not well-defined or communicated beyond the leadership team$qb$, $qb$Non-existent — the organisation does not have a defined growth vision$qb$, 5, 3, 2, 1, true),
  ($qb$S15C01Q02$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$The organisation's long-term growth strategy (3-5 year plan) is:$qb$, $qb$Documented, funded, and actively used to guide decisions$qb$, $qb$Defined — a strategy exists and is broadly followed$qb$, $qb$Partially defined — some strategic priorities are clear; others are ambiguous$qb$, $qb$Non-existent — the organisation operates without a defined long-term growth strategy$qb$, 5, 3, 2, 1, true),
  ($qb$S15C01Q03$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$Strategic priorities in your organisation are:$qb$, $qb$Clear, limited in number, and consistently communicated — all leaders know what they are$qb$, $qb$Generally clear — most leaders know the top priorities$qb$, $qb$Inconsistently understood — different people have different views of what the priorities are$qb$, $qb$Not clear — there is no shared view of the organisation's strategic priorities$qb$, 5, 3, 2, 1, true),
  ($qb$S15C01Q04$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$The quality of the strategic planning process in your organisation is:$qb$, $qb$Rigorous — strategy is developed through structured analysis, cross-functional input, and clear decision-making$qb$, $qb$Generally sound — the planning process is adequate$qb$, $qb$Inconsistent — strategic planning varies in quality and rigour$qb$, $qb$Poor — strategy is developed without adequate analysis or inclusive process$qb$, 5, 3, 2, 1, true),
  ($qb$S15C01Q05$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$Translation of strategy into annual operational plans in your organisation is:$qb$, $qb$Excellent — strategic priorities are translated into clear annual goals with owners, milestones, and metrics$qb$, $qb$Generally effective — most strategic priorities are reflected in operational plans$qb$, $qb$Partial — some strategic priorities are reflected in operational plans but not all$qb$, $qb$Weak — strategy and operational plans are not well-connected$qb$, 5, 3, 2, 1, true),
  ($qb$S15C01Q06$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$The organisation's ability to make bold strategic decisions when required is:$qb$, $qb$Strong — leadership is willing to make difficult decisions and move quickly when the strategy requires it$qb$, $qb$Adequate — major strategic decisions are made, though sometimes slower than optimal$qb$, $qb$Cautious — the organisation tends to delay bold decisions or avoid them$qb$, $qb$Very cautious — fear of failure prevents the organisation from making necessary strategic moves$qb$, 5, 3, 2, 1, true),
  ($qb$S15C01Q07$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$Scenario planning and strategic contingency planning in your organisation is:$qb$, $qb$Active — multiple strategic scenarios are regularly assessed and contingency plans exist$qb$, $qb$Periodic — some scenario planning occurs at annual planning time$qb$, $qb$Limited — scenario planning is not a regular strategic practice$qb$, $qb$Non-existent — the organisation plans for one future without scenario analysis$qb$, 5, 3, 2, 1, true),
  ($qb$S15C01Q08$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$Market and customer insight used in strategy development in your organisation is:$qb$, $qb$Deep — strategy is grounded in rigorous market and customer analysis$qb$, $qb$Adequate — relevant market data is used in strategy development$qb$, $qb$Limited — strategy is developed with limited market and customer insight$qb$, $qb$Poor — strategy is developed primarily from internal assumptions without external market grounding$qb$, 5, 3, 2, 1, true),
  ($qb$S15C01Q09$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$The organisation's growth strategy explicitly identifies the barriers it must remove to achieve its ambitions:$qb$, $qb$Yes — barrier identification and removal is an explicit part of the growth strategy$qb$, $qb$Partially — some barriers are identified but not comprehensively addressed in the strategy$qb$, $qb$Weakly — barriers are acknowledged but not structured into the strategic plan$qb$, $qb$No — the growth strategy focuses on opportunities without explicitly addressing barriers to achievement$qb$, 5, 3, 2, 1, true),
  ($qb$S15C01Q10$qb$, $qb$S15$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$Overall, the growth vision and strategic clarity in your organisation:$qb$, $qb$Is a genuine competitive advantage — clarity of purpose drives aligned execution$qb$, $qb$Is adequate — the strategy is clear enough to guide the organisation$qb$, $qb$Has notable gaps — strategic clarity problems are limiting organisational performance$qb$, $qb$Is a serious concern — lack of strategic clarity is causing significant organisational drift$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q01$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$The alignment of budget allocation with strategic priorities in your organisation is:$qb$, $qb$Tight — budget directly follows strategic priorities without significant mismatch$qb$, $qb$Generally aligned — most budget is directed to strategic priorities$qb$, $qb$Partially aligned — some budget is allocated to legacy activities that no longer reflect the strategy$qb$, $qb$Poorly aligned — budget allocation and stated strategic priorities are significantly disconnected$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q02$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$Investment in growth initiatives (new markets, new products, new capabilities) as a proportion of total investment is:$qb$, $qb$Well-calibrated — growth investment is at the level required to achieve the stated ambitions$qb$, $qb$Adequate — some meaningful growth investment is in place$qb$, $qb$Low — growth investment is insufficient relative to the stated ambitions$qb$, $qb$Very low — the organisation talks about growth but does not invest meaningfully in it$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q03$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$The organisation's willingness to make significant investments in growth when the case is clear is:$qb$, $qb$High — leadership backs well-argued investment cases decisively$qb$, $qb$Adequate — investment decisions are made with reasonable speed and confidence$qb$, $qb$Cautious — investment decisions are slow and subject to excessive scrutiny$qb$, $qb$Very cautious — a risk-averse culture prevents the organisation from making necessary growth investments$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q04$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$Capital allocation discipline (deploying capital to its highest-value uses) in your organisation is:$qb$, $qb$Rigorous — investment cases are assessed against clear criteria and capital goes to the best opportunities$qb$, $qb$Generally sound — major capital decisions are made with adequate rigour$qb$, $qb$Inconsistent — capital allocation is not always disciplined$qb$, $qb$Poor — capital allocation is driven by legacy, politics, or inertia rather than strategic value$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q05$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$People allocation to growth priorities (ensuring the right people work on the most important things) is:$qb$, $qb$Disciplined — the best people are deployed to the highest-priority growth initiatives$qb$, $qb$Generally adequate — most priority growth initiatives have strong people behind them$qb$, $qb$Inconsistent — people allocation to growth initiatives is not always aligned with priority$qb$, $qb$Poor — key talent is often absorbed by legacy operations rather than growth initiatives$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q06$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$The reallocation of resources from declining or low-priority activities to growth initiatives is:$qb$, $qb$Active — the organisation regularly stops or scales down lower-priority activities to free resource$qb$, $qb$Occasional — some reallocation happens but it is not a structured practice$qb$, $qb$Rare — the organisation tends to add new activities without stopping old ones$qb$, $qb$Non-existent — the organisation does not systematically reallocate resources from old to new priorities$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q07$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$The speed of resource mobilisation for growth opportunities in your organisation is:$qb$, $qb$Fast — when a growth opportunity is identified, resource is mobilised within weeks$qb$, $qb$Moderate — resource can be mobilised within a quarter$qb$, $qb$Slow — mobilising resource for new opportunities takes many months$qb$, $qb$Very slow — resource mobilisation for new opportunities is so slow that many opportunities are missed$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q08$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$The organisation's ability to fund growth internally (using operating cash flow) is:$qb$, $qb$Strong — the organisation generates sufficient cash to fund its growth agenda internally$qb$, $qb$Adequate — internal funding covers most growth needs$qb$, $qb$Limited — the organisation regularly needs external funding to support its growth ambitions$qb$, $qb$Very limited — the organisation cannot self-fund its growth and external capital access is constrained$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q09$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$Measurement and accountability for the return on growth investments in your organisation is:$qb$, $qb$Rigorous — all significant growth investments have defined expected returns that are tracked$qb$, $qb$Generally adequate — major growth investments are tracked$qb$, $qb$Partial — some growth investment tracking exists but it is not comprehensive$qb$, $qb$Weak — growth investments are made without systematic tracking of returns$qb$, 5, 3, 2, 1, true),
  ($qb$S15C02Q10$qb$, $qb$S15$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$Overall, resource allocation for growth in your organisation:$qb$, $qb$Is a genuine enabler of the growth strategy — resources are well-directed$qb$, $qb$Is adequate — resource allocation broadly supports the growth agenda$qb$, $qb$Has notable gaps — resource allocation misalignment is limiting growth execution$qb$, $qb$Is a serious barrier — poor resource allocation is a primary constraint on growth$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q01$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$The organisation's approach to innovation (new products, services, business models) is:$qb$, $qb$Systematic — innovation is funded, governed, and producing a regular pipeline of new offerings$qb$, $qb$Active — innovation is a stated priority with meaningful investment$qb$, $qb$Sporadic — innovation happens but without structure or consistency$qb$, $qb$Absent — the organisation does not invest meaningfully in innovation$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q02$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L+MM$qb$, $qb$The pipeline of new products or services in development in your organisation is:$qb$, $qb$Strong — a healthy pipeline exists with multiple offerings at different stages of development$qb$, $qb$Adequate — some new offerings are in development$qb$, $qb$Thin — the development pipeline is limited and does not provide sufficient future growth$qb$, $qb$Non-existent — the organisation has no meaningful pipeline of new products or services$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q03$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$Time-to-market for new products or services in your organisation is:$qb$, $qb$Fast — the organisation can develop and launch new offerings within months$qb$, $qb$Moderate — time-to-market is competitive with the market$qb$, $qb$Slow — the organisation is consistently slower to market than competitors$qb$, $qb$Very slow — lengthy development and approval cycles are a significant competitive disadvantage$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q04$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$New market entry capability (ability to enter new geographies or customer segments) in your organisation is:$qb$, $qb$Strong — the organisation has successfully entered new markets and has a repeatable playbook$qb$, $qb$Developing — some new market entry capability exists$qb$, $qb$Limited — new market entry is slow and uncertain$qb$, $qb$Very limited — the organisation has not meaningfully extended its geographic or segment reach$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q05$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$Customer co-creation in new product and service development in your organisation is:$qb$, $qb$Structured — customers are systematically involved in defining and testing new offerings$qb$, $qb$Occasional — customers are sometimes consulted during development$qb$, $qb$Rare — customer input into new product development is minimal$qb$, $qb$Non-existent — new products and services are developed without significant customer involvement$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q06$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L+MM$qb$, $qb$The organisation's tolerance for failure in innovation in your organisation is:$qb$, $qb$Healthy — calculated failures are expected and treated as learning$qb$, $qb$Moderate — some tolerance for innovation failure exists$qb$, $qb$Low — fear of failure significantly inhibits innovation experimentation$qb$, $qb$Very low — innovation is paralysed by the expectation that everything must succeed$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q07$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$Investment in R&D or structured innovation as a proportion of revenue in your organisation is:$qb$, $qb$At or above the sector benchmark — investment reflects the importance of innovation to growth$qb$, $qb$Adequate — some meaningful innovation investment is in place$qb$, $qb$Below sector benchmark — innovation underinvestment is limiting future growth capability$qb$, $qb$Very low — the organisation does not invest meaningfully in R&D or structured innovation$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q08$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L+MM$qb$, $qb$Learning from innovation failures in your organisation is:$qb$, $qb$Structured — lessons from failed innovations are captured and applied to future initiatives$qb$, $qb$Generally conducted — major failures are analysed$qb$, $qb$Occasional — some learning from failure occurs but not systematically$qb$, $qb$Non-existent — innovation failures are absorbed without structured learning$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q09$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$Strategic partnerships for growth (alliances, joint ventures, ecosystem development) in your organisation are:$qb$, $qb$Active and producing results — strategic partnerships are extending market reach and capability$qb$, $qb$Developing — some partnerships are in place$qb$, $qb$Limited — partnerships are not meaningfully contributing to growth$qb$, $qb$Non-existent — the organisation pursues growth independently without strategic partnerships$qb$, 5, 3, 2, 1, true),
  ($qb$S15C03Q10$qb$, $qb$S15$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$Overall, innovation and new market entry capability in your organisation:$qb$, $qb$Is a genuine competitive advantage — the organisation leads its market in bringing new things$qb$, $qb$Is developing — meaningful innovation capability is being built$qb$, $qb$Is limited — innovation and market extension are too slow for the growth ambition$qb$, $qb$Is a serious gap — inability to innovate or enter new markets is a major growth constraint$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q01$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$The organisation's systematic identification of barriers to growth in your organisation is:$qb$, $qb$Comprehensive — barriers are identified through structured analysis and are explicitly managed$qb$, $qb$Active — major barriers are identified and discussed at leadership level$qb$, $qb$Partial — some barriers are identified but the approach is not comprehensive$qb$, $qb$Non-existent — growth barriers are not systematically identified or addressed$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q02$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$Internal barriers to growth (processes, structures, culture, systems) in your organisation are:$qb$, $qb$Actively managed — internal barriers are identified, prioritised, and removed through deliberate action$qb$, $qb$Acknowledged — most internal barriers are known and some are being addressed$qb$, $qb$Known but unaddressed — significant internal barriers are known but not being removed$qb$, $qb$Not identified — the organisation has not formally assessed what internal barriers are constraining growth$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q03$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$External barriers to growth (market access, regulation, competition, technology) in your organisation are:$qb$, $qb$Actively managed — external barriers are identified and strategies exist to address them$qb$, $qb$Acknowledged — major external barriers are known and some mitigation is in place$qb$, $qb$Partially managed — some external barriers are addressed; others are not$qb$, $qb$Not managed — external barriers to growth are not systematically assessed or addressed$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q04$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$The pace at which barriers are removed relative to the organisation's growth ambition is:$qb$, $qb$Fast enough — barriers are being removed at the speed required to achieve the growth plan$qb$, $qb$Adequate — barriers are being removed but with some lag behind the growth timeline$qb$, $qb$Too slow — barrier removal is consistently lagging behind the growth ambition$qb$, $qb$Very slow — growth is being significantly constrained by the accumulation of unresolved barriers$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q05$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$Leadership accountability for barrier removal in your organisation is:$qb$, $qb$Clear — specific leaders are responsible for removing specific barriers with timelines and metrics$qb$, $qb$Generally present — most barriers have an owner$qb$, $qb$Inconsistent — some barriers have clear ownership; others do not$qb$, $qb$Absent — no one is specifically accountable for identifying and removing growth barriers$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q06$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$The organisation's use of external expertise (consultants, advisors) to identify and remove growth barriers is:$qb$, $qb$Strategic — external expertise is selectively used to accelerate barrier removal$qb$, $qb$Occasional — external support is brought in for specific barrier challenges$qb$, $qb$Rare — external expertise for growth barrier removal is infrequent$qb$, $qb$Non-existent — the organisation does not use external expertise for growth barrier identification$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q07$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$Employee involvement in identifying growth barriers in your organisation is:$qb$, $qb$Active — frontline employees are regularly consulted on what is preventing better performance$qb$, $qb$Occasional — some employee input is sought on barriers to growth$qb$, $qb$Limited — barrier identification is primarily a leadership activity without meaningful employee input$qb$, $qb$Non-existent — employees are not asked to identify what is blocking growth$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q08$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$The organisation's culture's attitude to removing structural barriers to growth is:$qb$, $qb$Change-embracing — difficult structural changes are accepted as necessary for growth$qb$, $qb$Generally open — the organisation is willing to make structural changes when needed$qb$, $qb$Cautious — structural changes are approached conservatively and slowly$qb$, $qb$Very resistant — cultural resistance to change is itself a significant barrier to growth$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q09$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$The use of data and analytics to identify and prioritise growth barriers in your organisation is:$qb$, $qb$Sophisticated — data drives the identification, prioritisation, and tracking of barrier removal$qb$, $qb$Adequate — relevant data is used in barrier assessment$qb$, $qb$Limited — barrier identification relies primarily on judgment without strong data support$qb$, $qb$Non-existent — growth barrier identification is not data-driven$qb$, 5, 3, 2, 1, true),
  ($qb$S15C04Q10$qb$, $qb$S15$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$Overall, the organisation's capability to identify and remove growth barriers:$qb$, $qb$Is a genuine competitive strength — the organisation removes barriers faster than competitors$qb$, $qb$Is adequate — barriers are identified and addressed with reasonable effectiveness$qb$, $qb$Has notable gaps — barrier removal is too slow for the growth ambition$qb$, $qb$Is a significant weakness — the accumulation of unresolved barriers is a primary growth constraint$qb$, 5, 3, 2, 1, true),
